package com.manu.ai;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.provider.Settings;import android.text.InputType;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.util.*;

public class MainActivity extends Activity{
 private LinearLayout messages;private ScrollView scroll;private EditText input;private TextView status;private Button send;private View welcome,thinking;private IntentRouter router;private LocalModel model;private MemoryStore memory;private boolean restoring;private String lastPrompt="";private final int ink=Color.rgb(32,33,36),muted=Color.rgb(116,119,124),line=Color.rgb(226,228,230),surface=Color.rgb(245,246,247),accent=Color.rgb(22,125,100);
 public void onCreate(Bundle b){super.onCreate(b);setTitle("MANU · Asistente local");setRequestedOrientation(1);router=new IntentRouter(this);model=new LocalModel(this);memory=new MemoryStore(this);getWindow().setStatusBarColor(Color.WHITE);getWindow().setNavigationBarColor(Color.WHITE);if(Build.VERSION.SDK_INT>=29)getWindow().setNavigationBarContrastEnforced(false);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);build();restoreConversation();}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} TextView label(String s,float size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;} GradientDrawable shape(int color,float radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp((int)radius));return d;}
 void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.WHITE);root.setPadding(dp(16),dp(8),dp(16),dp(8));root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(16),i.getSystemWindowInsetTop()+dp(8),dp(16),i.getSystemWindowInsetBottom()+dp(8));return i;});
  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView avatar=label("M",16,Color.WHITE);avatar.setGravity(Gravity.CENTER);avatar.setBackground(shape(accent,50));top.addView(avatar,new LinearLayout.LayoutParams(dp(40),dp(40)));LinearLayout identity=new LinearLayout(this);identity.setOrientation(LinearLayout.VERTICAL);identity.setPadding(dp(12),0,0,0);TextView title=label("MANU (Modelo Autónomo Neural Útil)",14,ink);title.setTypeface(null,1);title.setSingleLine(true);title.setGravity(Gravity.CENTER_VERTICAL);identity.addView(title,new LinearLayout.LayoutParams(-1,dp(22)));status=label(model.isAvailable()?"IA local · sin conexión":"Modo básico",12,muted);status.setGravity(Gravity.CENTER_VERTICAL);identity.addView(status,new LinearLayout.LayoutParams(-1,dp(20)));top.addView(identity,new LinearLayout.LayoutParams(0,dp(44),1));TextView more=label("⋮",24,muted);more.setGravity(Gravity.CENTER);more.setContentDescription("Más opciones");top.addView(more,new LinearLayout.LayoutParams(dp(36),dp(44)));root.addView(top,new LinearLayout.LayoutParams(-1,dp(48)));
  View divider=new View(this);divider.setBackgroundColor(line);root.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));
  scroll=new ScrollView(this);scroll.setFillViewport(true);messages=new LinearLayout(this);messages.setOrientation(LinearLayout.VERTICAL);messages.setPadding(dp(4),dp(20),dp(4),dp(20));scroll.addView(messages,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout composer=new LinearLayout(this);composer.setGravity(Gravity.CENTER_VERTICAL);composer.setPadding(dp(14),dp(4),dp(5),dp(4));composer.setBackground(shape(surface,28));input=new EditText(this);input.setHint("Pregunta lo que quieras");input.setHintTextColor(muted);input.setTextColor(ink);input.setTextSize(15);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES|InputType.TYPE_TEXT_FLAG_MULTI_LINE);input.setSingleLine(false);input.setMinLines(1);input.setMaxLines(4);input.setGravity(Gravity.CENTER_VERTICAL);input.setPadding(0,0,dp(8),0);input.setBackgroundColor(Color.TRANSPARENT);input.setContentDescription("Escribe un mensaje");composer.addView(input,new LinearLayout.LayoutParams(0,dp(52),1));send=roundButton("↑",accent,"Enviar mensaje");send.setEnabled(false);composer.addView(send,new LinearLayout.LayoutParams(dp(44),dp(44)));send.setOnClickListener(v->send());LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(10),0,0);root.addView(composer,cp);setContentView(root);input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){send.setEnabled(s.toString().trim().length()>0);}public void afterTextChanged(android.text.Editable e){}});showWelcome();}
 Button roundButton(String s,int color,String desc){Button b=new Button(this);b.setText(s);b.setTextSize(20);b.setTextColor(Color.WHITE);b.setGravity(Gravity.CENTER);b.setPadding(0,0,0,dp(2));b.setBackground(shape(color,50));b.setContentDescription(desc);return b;}
 void showWelcome(){welcome=new LinearLayout(this);((LinearLayout)welcome).setOrientation(LinearLayout.VERTICAL);((LinearLayout)welcome).setGravity(Gravity.CENTER_HORIZONTAL);TextView big=label("MANU",28,ink);big.setTypeface(null,1);big.setGravity(Gravity.CENTER);((LinearLayout)welcome).addView(big,new LinearLayout.LayoutParams(-1,dp(42)));TextView tagline=label("Tu inteligencia, en tu dispositivo.",16,muted);tagline.setGravity(Gravity.CENTER);((LinearLayout)welcome).addView(tagline,new LinearLayout.LayoutParams(-1,dp(32)));TextView hello=label("Hola, soy MANU. ¿En qué puedo ayudarte hoy?",16,ink);hello.setGravity(Gravity.CENTER);hello.setPadding(dp(12),dp(12),dp(12),dp(22));((LinearLayout)welcome).addView(hello,new LinearLayout.LayoutParams(-1,-2));String[] options={"¿Qué puedes hacer?","Ayúdame con una pregunta","Abrir una aplicación"};for(String option:options){Button b=new Button(this);b.setText(option);b.setTextSize(13);b.setTextColor(ink);b.setAllCaps(false);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setPadding(dp(16),0,dp(10),0);b.setBackground(shape(surface,16));b.setContentDescription(option);b.setOnClickListener(v->{input.setText(option);input.requestFocus();send();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(300),dp(46));p.setMargins(0,0,0,dp(8));((LinearLayout)welcome).addView(b,p);}LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(-1,-2);wp.setMargins(0,dp(90),0,0);messages.addView(welcome,wp);}
 void beginConversation(){if(welcome!=null){messages.removeView(welcome);welcome=null;}}
 void addMessage(String msg,boolean mine){if(!restoring)memory.addMessage(mine?"user":"assistant",msg);beginConversation();LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);TextView body=label(msg,15,ink);body.setTextIsSelectable(true);body.setLineSpacing(0,1.18f);body.setMaxWidth(dp(320));if(mine)body.setPadding(dp(14),dp(9),dp(14),dp(9));else body.setPadding(dp(40),0,dp(8),0);if(mine)body.setBackground(shape(Color.rgb(242,243,244),18));row.addView(body,new LinearLayout.LayoutParams(-2,-2));if(!mine){LinearLayout actions=new LinearLayout(this);actions.setPadding(dp(40),dp(4),0,0);Button copy=smallAction("Copiar");copy.setOnClickListener(v->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(android.content.ClipData.newPlainText("MANU",msg));Toast.makeText(this,"Respuesta copiada",Toast.LENGTH_SHORT).show();});actions.addView(copy);Button regen=smallAction("Regenerar");regen.setOnClickListener(v->{if(!lastPrompt.isEmpty())request(lastPrompt,false);});actions.addView(regen);row.addView(actions,new LinearLayout.LayoutParams(-1,dp(32)));}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(18));messages.addView(row,p);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}
 Button smallAction(String s){Button b=new Button(this);b.setText(s);b.setTextSize(11);b.setTextColor(muted);b.setAllCaps(false);b.setPadding(0,0,dp(12),0);b.setBackgroundColor(Color.TRANSPARENT);return b;}
 void addThinking(){if(thinking!=null)return;PerformanceView graph=new PerformanceView(this);graph.start();thinking=graph;LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(92));p.setMargins(dp(40),dp(4),dp(40),dp(16));messages.addView(thinking,p);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}
 void removeThinking(){if(thinking!=null){if(thinking instanceof PerformanceView)((PerformanceView)thinking).stop();messages.removeView(thinking);thinking=null;}}
 void send(){String q=input.getText().toString().trim();if(q.isEmpty()||!send.isEnabled())return;input.setText("");addMessage(q,true);lastPrompt=q;request(q,false);}
 void request(String q,boolean addUser){if(addUser)addMessage(q,true);send.setEnabled(false);status.setText("MANU está pensando…");addThinking();IntentResult r=router.route(q);if(r.kind!=IntentResult.Kind.UNKNOWN){if(r.kind==IntentResult.Kind.OPEN_APP)open(r.a);else if(r.kind==IntentResult.Kind.SMS_CONFIRM)new AlertDialog.Builder(this).setTitle("Confirmar mensaje").setMessage(r.b).setNegativeButton("Cancelar",null).setPositiveButton("Abrir mensajes",(d,w)->sms(r.b)).show();else finishResponse(r.text);if(r.kind==IntentResult.Kind.OPEN_APP)finishResponse(r.text);return;}if(model.isAvailable())model.ask(memory.contextFor(q),(a,e)->finishResponse(e!=null?e:a));else finishResponse("Todavía no tengo una herramienta para esa tarea.");}
 void finishResponse(String answer){removeThinking();addMessage(answer,false);send.setEnabled(input.getText().toString().trim().length()>0);if(model.isAvailable()&&model.getLastElapsedMs()>0){double approxTokens=Math.max(1,model.getLastOutputChars()/4d);double rate=approxTokens/(model.getLastElapsedMs()/1000d);status.setText(String.format(Locale.getDefault(),"IA local · %.1f s · ~%.1f tok/s",model.getLastElapsedMs()/1000d,rate));}else status.setText("Modo básico");}
 void sms(String body){Intent i=new Intent(Intent.ACTION_SENDTO,Uri.parse("smsto:"));i.putExtra("sms_body",body);startActivity(i);}
 void open(String name){String l=name.toLowerCase(Locale.ROOT),pkg=l.contains("youtube")?"com.google.android.youtube":l.contains("whatsapp")?"com.whatsapp":l.contains("chrome")?"com.android.chrome":l.contains("ajuste")?"com.android.settings":null;try{Intent i=pkg==null?new Intent(Settings.ACTION_SETTINGS):getPackageManager().getLaunchIntentForPackage(pkg);if(i!=null)startActivity(i);else finishResponse("No encuentro esa aplicación instalada.");}catch(Exception e){finishResponse("No pude abrir esa aplicación.");}}
 void restoreConversation(){if(!memory.hasMessages())return;if(welcome!=null){messages.removeView(welcome);welcome=null;}restoring=true;for(String[]m:memory.recent(40))addMessage(m[1],"user".equals(m[0]));restoring=false;}
}
